export function taxRate(country: string): number {
  if (country === "US") return 0;
  if (EU.includes(country)) return VAT[country];
  throw new Error(`No tax rate for ${country}`);
}
const EU = ["DE", "FR", "NL"];
const VAT: Record<string, number> = { DE: 0.19, FR: 0.2 };
